# Generated by build.py from recipe.yml for recipe http-follow-links-inside-the-served-folder. Do not edit.
Set-Location $PSScriptRoot
New-Item -ItemType Directory -Force -Path 'site/docs', 'plain/docs', 'outside' | Out-Null
[IO.File]::WriteAllText((Join-Path $PWD 'site/docs/guide.txt'), "the guide, inside the served folder`n")
[IO.File]::WriteAllText((Join-Path $PWD 'plain/docs/guide.txt'), "the guide, inside the served folder`n")
[IO.File]::WriteAllText((Join-Path $PWD 'outside/secret.txt'), "outside the served folder`n")
[IO.File]::WriteAllText((Join-Path $PWD 'make-links.sh'), "#!/bin/sh`n# Copyright (c) 2026 Stewart Rogers. Apache License 2.0. See Book/LICENSE-CODE.txt.`n# Makes the same four symbolic links in site and in plain. MSYS asks Git Bash on Windows`n# for real links; other systems ignore it.`nexport MSYS=winsymlinks:nativestrict`nfor root in site plain; do`n  ln -s docs/guide.txt `"`$root/latest.txt`"          # a file link that stays inside`n  ln -s docs `"`$root/current`"                        # a folder link that stays inside`n  ln -s ../outside/secret.txt `"`$root/leak.txt`"      # a link that leaves the folder`n  ln -s leak.txt `"`$root/hop.txt`"                    # a link inside to a link that leaves`ndone`n")
cmd /c 'sh make-links.sh'
$server0 = Start-Process surl -ArgumentList '-v', '--log-file', 'links.log', '--follow-symlinks', '--directory', 'site', 'http://127.0.0.1:8080/' -PassThru -NoNewWindow
Start-Sleep 1
try { curl.exe -s -w "%{http_code}\n" http://127.0.0.1:8080/latest.txt } finally { Stop-Process $server0 }
